window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9e6c89f4c3b31578"]={"versions": [{"id": "FIG-9e6c89f4c3b31578", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Aktivitätsdiagramm (Activity Diagram) zur Spezifikation eines algorithmischen Einzelschritts.</li>\n<li><strong>Technischer Zweck:</strong> Generische Musterspezifikation (<code>PXX</code>) für den Teilschritt „Write Counter“ innerhalb der E2E-Senderoutine <code>E2E_PXXProtect()</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Bestandteil der AUTOSAR E2E Library (Classic Platform) bzw. des E2E Protected Data Routing (Adaptive Platform). Dient der Absicherung gegen Übertragungsfehler wie Nachrichtenverlust (Loss), Duplikate (Repetition) und Reihenfolgevertauschungen (Resequencing) gemäß <code>RS_E2E_08539</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätskontext:</strong></li>\n<li><code>E2E_PXXProtect()</code>: Senderseitige Schutzfunktion für ein beliebiges Profil <code>XX</code> (z. B. P04, P05, P11, P22).</li>\n<li><strong>Datenstrukturen & Parameter:</strong></li>\n<li><code>State</code> (<code>IN/OUT</code>, Typ <code>E2E_PXXProtectStateType*</code>): Zustandsstruktur der E2E-Instanz. Enthält das Element <code>Counter</code> (aktueller Sendezähler / Alive Counter).</li>\n<li><code>Data</code> (<code>IN/OUT</code>, Typ <code>uint8*</code>): Linearer Byte-Puffer der Nutzlast/PDU, in den der Zähler serialisiert wird.</li>\n<li><code>Offset</code> (<code>IN</code>, profilabhängig als Konfigurationsparameter in <code>E2E_PXXConfigType</code> oder Laufzeitargument): Byte-Verschiebung des E2E-Headers innerhalb des PDU-Puffers.</li>\n<li><strong>Profilspezifische Konstanten/Platzhalter:</strong></li>\n<li><code>PXXCOUNTER_LEN</code>: Zählerlänge in Bytes.</li>\n<li><code>PXXCOUNTER_POS</code>: Relative Byte-Position des Zählers bezogen auf <code>Offset</code>.</li>\n<li><strong>Relationen & Adressierungsbereich:</strong></li>\n<li>Das Byte-Intervall im Zielpuffer <code>Data</code> ist exakt definiert als:</li>\n</ul>\n<p class=\"fig-p\">$[\\text{Offset} + \\text{PXXCOUNTER\\_POS} \\,,\\, \\text{Offset} + \\text{PXXCOUNTER\\_POS} + \\text{PXXCOUNTER\\_LEN} - 1]$.</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Teilschritt unmittelbar nach Abschluss vorgelagerter Schritte (wie z. B. „Write Length“ gemäß <code>PRS_E2E_01212</code>).</li>\n<li><strong>Action Node (<code>Copy parameter State-&gt;Counter to bytstring Data</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchroner Kopiervorgang / Serialisierung des aktuellen numerischen Werts aus <code>State-&gt;Counter</code> in das definierte Byte-Intervall von <code>Data</code>.</li>\n<li>Profilspezifische Endianness-Ausrichtung (in der Regel Big-Endian / Network Byte Order bei $\\text{PXXCOUNTER\\_LEN} > 1$).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Activity Final Node:</strong> Beendigung des Schritts und Übergang zur anschließenden CRC-Berechnung (<code>Compute CRC</code>, z. B. <code>PRS_E2E_01214</code>).</li>\n<li><strong>Fehlerbehandlung:</strong> Keine lokalen Verzweigungen oder Det/Dem-Meldungen; Vorbedingungen (z. B. <code>Data != NULL</code>, <code>State != NULL</code>) werden zwingend am Funktionseingang von <code>E2E_PXXProtect()</code> validiert (<code>E2E_E_INPUTERR_NULL</code>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung (<code>PRS_E2E_01213</code>):</strong> Die Implementierung der Schutzfunktion muss zwingend das in Figure 6.6 definierte Schreibverhalten für den Zähler einhalten.</li>\n<li><strong>Zustandskonsistenz:</strong> <code>State-&gt;Counter</code> wird in diesem Schritt ausschließlich <em>gelesen</em> und in den Puffer geschrieben. Das eigentliche Inkrementieren des Counters (<code>State-&gt;Counter++</code>) erfolgt normativ erst in einem separaten, nachgelagerten Schritt (typischerweise am Ende von <code>E2E_PXXProtect()</code>, um den Counter nur bei vollständig geschützter Nachricht hochzuzählen).</li>\n<li><strong>Nibble-basierte Profile (Sonderfall):</strong> Bei Profilen mit Sub-Byte-Countern (z. B. 4-Bit-Zähler in Profil 01/02) gilt das gezeigte Byte-Schema sinngemäß mit Maskierungs- und Shift-Operationen, um angrenzende Header-Informationen (wie Data ID Nibbles) im selben Byte nicht zu korrumpieren.</li>\n<li><strong>Puffersicherheit:</strong> Der Aufrufer (E2E-Transformer / RTE / COM-Stack) muss sicherstellen, dass die allozierte Puffergröße von <code>Data</code> mindestens $\\text{Offset} + \\text{PXXCOUNTER\\_POS} + \\text{PXXCOUNTER\\_LEN}$ Bytes umfasst, um Out-of-Bounds-Schreibzugriffe zu verhindern.</li>\n</ul>"}, {"id": "FIG-83ae653634c10cb0", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Aktivitätsdiagramm (Activity Diagram) zur Spezifikation eines algorithmischen Einzelschritts.</li>\n<li><strong>Technischer Zweck:</strong> Generische Musterspezifikation (<code>PXX</code>) für den Teilschritt „Write Counter“ innerhalb der E2E-Senderoutine <code>E2E_PXXProtect()</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Bestandteil der AUTOSAR E2E Library (Classic Platform) bzw. des E2E Protected Data Routing (Adaptive Platform). Dient der Absicherung gegen Übertragungsfehler wie Nachrichtenverlust (Loss), Duplikate (Repetition) und Reihenfolgevertauschungen (Resequencing) gemäß <code>RS_E2E_08539</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätskontext:</strong></li>\n<li><code>E2E_PXXProtect()</code>: Senderseitige Schutzfunktion für ein beliebiges Profil <code>XX</code> (z. B. P04, P05, P11, P22).</li>\n<li><strong>Datenstrukturen & Parameter:</strong></li>\n<li><code>State</code> (<code>IN/OUT</code>, Typ <code>E2E_PXXProtectStateType*</code>): Zustandsstruktur der E2E-Instanz. Enthält das Element <code>Counter</code> (aktueller Sendezähler / Alive Counter).</li>\n<li><code>Data</code> (<code>IN/OUT</code>, Typ <code>uint8*</code>): Linearer Byte-Puffer der Nutzlast/PDU, in den der Zähler serialisiert wird.</li>\n<li><code>Offset</code> (<code>IN</code>, profilabhängig als Konfigurationsparameter in <code>E2E_PXXConfigType</code> oder Laufzeitargument): Byte-Verschiebung des E2E-Headers innerhalb des PDU-Puffers.</li>\n<li><strong>Profilspezifische Konstanten/Platzhalter:</strong></li>\n<li><code>PXXCOUNTER_LEN</code>: Zählerlänge in Bytes.</li>\n<li><code>PXXCOUNTER_POS</code>: Relative Byte-Position des Zählers bezogen auf <code>Offset</code>.</li>\n<li><strong>Relationen & Adressierungsbereich:</strong></li>\n<li>Das Byte-Intervall im Zielpuffer <code>Data</code> ist exakt definiert als:</li>\n</ul>\n<p class=\"fig-p\">$[\\text{Offset} + \\text{PXXCOUNTER\\_POS} \\,,\\, \\text{Offset} + \\text{PXXCOUNTER\\_POS} + \\text{PXXCOUNTER\\_LEN} - 1]$.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Teilschritt unmittelbar nach Abschluss vorgelagerter Schritte (wie z. B. „Write Length“ gemäß <code>PRS_E2E_01212</code>).</li>\n<li><strong>Action Node (<code>Copy parameter State-&gt;Counter to bytstring Data</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchroner Kopiervorgang / Serialisierung des aktuellen numerischen Werts aus <code>State-&gt;Counter</code> in das definierte Byte-Intervall von <code>Data</code>.</li>\n<li>Profilspezifische Endianness-Ausrichtung (in der Regel Big-Endian / Network Byte Order bei $\\text{PXXCOUNTER\\_LEN} > 1$).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Activity Final Node:</strong> Beendigung des Schritts und Übergang zur anschließenden CRC-Berechnung (<code>Compute CRC</code>, z. B. <code>PRS_E2E_01214</code>).</li>\n<li><strong>Fehlerbehandlung:</strong> Keine lokalen Verzweigungen oder Det/Dem-Meldungen; Vorbedingungen (z. B. <code>Data != NULL</code>, <code>State != NULL</code>) werden zwingend am Funktionseingang von <code>E2E_PXXProtect()</code> validiert (<code>E2E_E_INPUTERR_NULL</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung (<code>PRS_E2E_01213</code>):</strong> Die Implementierung der Schutzfunktion muss zwingend das in Figure 6.6 definierte Schreibverhalten für den Zähler einhalten.</li>\n<li><strong>Zustandskonsistenz:</strong> <code>State-&gt;Counter</code> wird in diesem Schritt ausschließlich <em>gelesen</em> und in den Puffer geschrieben. Das eigentliche Inkrementieren des Counters (<code>State-&gt;Counter++</code>) erfolgt normativ erst in einem separaten, nachgelagerten Schritt (typischerweise am Ende von <code>E2E_PXXProtect()</code>, um den Counter nur bei vollständig geschützter Nachricht hochzuzählen).</li>\n<li><strong>Nibble-basierte Profile (Sonderfall):</strong> Bei Profilen mit Sub-Byte-Countern (z. B. 4-Bit-Zähler in Profil 01/02) gilt das gezeigte Byte-Schema sinngemäß mit Maskierungs- und Shift-Operationen, um angrenzende Header-Informationen (wie Data ID Nibbles) im selben Byte nicht zu korrumpieren.</li>\n<li><strong>Puffersicherheit:</strong> Der Aufrufer (E2E-Transformer / RTE / COM-Stack) muss sicherstellen, dass die allozierte Puffergröße von <code>Data</code> mindestens $\\text{Offset} + \\text{PXXCOUNTER\\_POS} + \\text{PXXCOUNTER\\_LEN}$ Bytes umfasst, um Out-of-Bounds-Schreibzugriffe zu verhindern.</li>\n</ul>"}, {"id": "FIG-fb063f1af5ffce4f", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Aktivitätsdiagramm (Activity Diagram) zur Spezifikation eines algorithmischen Einzelschritts.</li>\n<li><strong>Technischer Zweck:</strong> Generische Musterspezifikation (<code>PXX</code>) für den Teilschritt „Write Counter“ innerhalb der E2E-Senderoutine <code>E2E_PXXProtect()</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Bestandteil der AUTOSAR E2E Library (Classic Platform) bzw. des E2E Protected Data Routing (Adaptive Platform). Dient der Absicherung gegen Übertragungsfehler wie Nachrichtenverlust (Loss), Duplikate (Repetition) und Reihenfolgevertauschungen (Resequencing) gemäß <code>RS_E2E_08539</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätskontext:</strong></li>\n<li><code>E2E_PXXProtect()</code>: Senderseitige Schutzfunktion für ein beliebiges Profil <code>XX</code> (z. B. P04, P05, P11, P22).</li>\n<li><strong>Datenstrukturen & Parameter:</strong></li>\n<li><code>State</code> (<code>IN/OUT</code>, Typ <code>E2E_PXXProtectStateType*</code>): Zustandsstruktur der E2E-Instanz. Enthält das Element <code>Counter</code> (aktueller Sendezähler / Alive Counter).</li>\n<li><code>Data</code> (<code>IN/OUT</code>, Typ <code>uint8*</code>): Linearer Byte-Puffer der Nutzlast/PDU, in den der Zähler serialisiert wird.</li>\n<li><code>Offset</code> (<code>IN</code>, profilabhängig als Konfigurationsparameter in <code>E2E_PXXConfigType</code> oder Laufzeitargument): Byte-Verschiebung des E2E-Headers innerhalb des PDU-Puffers.</li>\n<li><strong>Profilspezifische Konstanten/Platzhalter:</strong></li>\n<li><code>PXXCOUNTER_LEN</code>: Zählerlänge in Bytes.</li>\n<li><code>PXXCOUNTER_POS</code>: Relative Byte-Position des Zählers bezogen auf <code>Offset</code>.</li>\n<li><strong>Relationen & Adressierungsbereich:</strong></li>\n<li>Das Byte-Intervall im Zielpuffer <code>Data</code> ist exakt definiert als:</li>\n</ul>\n<p class=\"fig-p\">$[\\text{Offset} + \\text{PXXCOUNTER\\_POS} \\,,\\, \\text{Offset} + \\text{PXXCOUNTER\\_POS} + \\text{PXXCOUNTER\\_LEN} - 1]$.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Teilschritt unmittelbar nach Abschluss vorgelagerter Schritte (wie z. B. „Write Length“ gemäß <code>PRS_E2E_01212</code>).</li>\n<li><strong>Action Node (<code>Copy parameter State-&gt;Counter to bytstring Data</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchroner Kopiervorgang / Serialisierung des aktuellen numerischen Werts aus <code>State-&gt;Counter</code> in das definierte Byte-Intervall von <code>Data</code>.</li>\n<li>Profilspezifische Endianness-Ausrichtung (in der Regel Big-Endian / Network Byte Order bei $\\text{PXXCOUNTER\\_LEN} > 1$).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Activity Final Node:</strong> Beendigung des Schritts und Übergang zur anschließenden CRC-Berechnung (<code>Compute CRC</code>, z. B. <code>PRS_E2E_01214</code>).</li>\n<li><strong>Fehlerbehandlung:</strong> Keine lokalen Verzweigungen oder Det/Dem-Meldungen; Vorbedingungen (z. B. <code>Data != NULL</code>, <code>State != NULL</code>) werden zwingend am Funktionseingang von <code>E2E_PXXProtect()</code> validiert (<code>E2E_E_INPUTERR_NULL</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung (<code>PRS_E2E_01213</code>):</strong> Die Implementierung der Schutzfunktion muss zwingend das in Figure 6.6 definierte Schreibverhalten für den Zähler einhalten.</li>\n<li><strong>Zustandskonsistenz:</strong> <code>State-&gt;Counter</code> wird in diesem Schritt ausschließlich <em>gelesen</em> und in den Puffer geschrieben. Das eigentliche Inkrementieren des Counters (<code>State-&gt;Counter++</code>) erfolgt normativ erst in einem separaten, nachgelagerten Schritt (typischerweise am Ende von <code>E2E_PXXProtect()</code>, um den Counter nur bei vollständig geschützter Nachricht hochzuzählen).</li>\n<li><strong>Nibble-basierte Profile (Sonderfall):</strong> Bei Profilen mit Sub-Byte-Countern (z. B. 4-Bit-Zähler in Profil 01/02) gilt das gezeigte Byte-Schema sinngemäß mit Maskierungs- und Shift-Operationen, um angrenzende Header-Informationen (wie Data ID Nibbles) im selben Byte nicht zu korrumpieren.</li>\n<li><strong>Puffersicherheit:</strong> Der Aufrufer (E2E-Transformer / RTE / COM-Stack) muss sicherstellen, dass die allozierte Puffergröße von <code>Data</code> mindestens $\\text{Offset} + \\text{PXXCOUNTER\\_POS} + \\text{PXXCOUNTER\\_LEN}$ Bytes umfasst, um Out-of-Bounds-Schreibzugriffe zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-9e6c89f4c3b31578", "to": "FIG-83ae653634c10cb0", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Oberer Bildbeschnitt korrigiert: Die in R23-11 am oberen Rand sichtbaren Textfragmente („ave as shown in Figure 6.5] (RS“) der vorangehenden Textzeile wurden entfernt.</li>\n<li>Inhaltlich unverändert.</li>\n</ul>"}, {"from": "FIG-83ae653634c10cb0", "to": "FIG-fb063f1af5ffce4f", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
